/** IDs only; absent media is intentionally silent. No network/audio playback is needed for gameplay. */
export const AUDIO_MANIFEST=Object.freeze(Object.fromEntries(['weather.rain.light','weather.rain.heavy','battle.transition','battle.default','map.coast','ambient.coast',...['BODY_HIT','BODY_CHARGE','WATER_PROJECTILE','WATER_WAVE','LEAF_SLASH','LEAF_BURST','ELECTRIC_BURST','ELECTRIC_BEAM','POISON_CLOUD','POISON_SPLASH','ROCK_IMPACT','ROCK_PROJECTILE','WIND_GUST','AIR_SLASH','GROUND_IMPACT','HEAL_GLOW','BUFF_AURA','DEBUFF_AURA','STATUS_EFFECT','SPECIAL_FLASH'].map(f=>'move.'+f)].map(id=>[id,Object.freeze({id,src:null})])));
export function resolveAudio(id,manifest=AUDIO_MANIFEST){const asset=manifest[id];return asset?.src?{...asset,silent:false}:{id:id??null,src:null,silent:true}}
export function createAudioHooks(){const listeners=new Set();return {subscribe(fn){listeners.add(fn);return ()=>listeners.delete(fn)},emit(id,metadata={}){const event=Object.freeze({...resolveAudio(id),...metadata,id:id??null});for(const fn of listeners)try{Promise.resolve(fn(event)).catch(()=>{})}catch{}return event}}}
export const presentationAudio=createAudioHooks();
/** One router per field/session. Empty optional IDs emit silence; repeated render frames do not replay hooks. */
export function createMapAudioRouter(hooks=presentationAudio){let previous=null;return {update(map={},battleActive=false){const signature=JSON.stringify([map.id??map.biomeId??null,map.bgmId??null,map.ambientId??null,battleActive]);if(signature===previous)return false;previous=signature;hooks.emit(battleActive?null:map.bgmId,{channel:'map-bgm',mapId:map.id??null});hooks.emit(battleActive?null:map.ambientId,{channel:'map-ambient',mapId:map.id??null});return true}}}
